import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { trigger, transition, style, animate, stagger, query } from '@angular/animations';

interface Artist {
  id: string;
  name: string;
  bio: string;
  specialty: string;
  location: string;
  image: string;
  artworks: number;
  joinedDate: string;
  socialLinks: {
    instagram?: string;
    twitter?: string;
    website?: string;
  };
}

@Component({
  selector: 'app-artists',
  standalone: true,
  imports: [CommonModule],
  template: `
    <div class="artists-container" [@fadeInUp]>
      <!-- Hero Section -->
      <section class="artists-hero">
        <div class="hero-content">
          <h1 class="hero-title">Meet Our Artists</h1>
          <p class="hero-subtitle">Discover the talented creators behind our amazing collection of artworks</p>
        </div>
      </section>

      <!-- Filter Section -->
      <section class="filter-section">
        <div class="filter-container">
          <div class="filter-group">
            <label class="filter-label">Search Artists</label>
            <input 
              type="text" 
              [(ngModel)]="searchTerm"
              (input)="filterArtists()"
              placeholder="Search by name, specialty, or location..."
              class="search-input">
          </div>
          
          <div class="filter-group">
            <label class="filter-label">Specialty</label>
            <select 
              [(ngModel)]="selectedSpecialty"
              (change)="filterArtists()"
              class="filter-select">
              <option value="">All Specialties</option>
              <option *ngFor="let specialty of specialties" [value]="specialty">
                {{ specialty }}
              </option>
            </select>
          </div>
        </div>
      </section>

      <!-- Artists Grid -->
      <section class="artists-section">
        <div class="artists-header">
          <h2 class="section-title">Featured Artists</h2>
